// Gym exercise library. Sources: research rules (docs/SPEC.md) + transcripts (docs/kunskap/gym-transkript.md, level D).

export type Muscle =
  | 'chest' | 'lats' | 'upper_back' | 'front_delt' | 'side_delt' | 'rear_delt'
  | 'biceps' | 'triceps' | 'quads' | 'hamstrings' | 'glutes' | 'calves' | 'abs' | 'traps' | 'forearms';

export const MUSCLES: Muscle[] = ['chest', 'lats', 'upper_back', 'front_delt', 'side_delt', 'rear_delt', 'biceps', 'triceps', 'quads', 'hamstrings', 'glutes', 'calves', 'abs'];

export const MUSCLE_NAME: Record<Muscle, string> = {
  chest: 'Bröst', lats: 'Lats', upper_back: 'Övre rygg', front_delt: 'Främre axel', side_delt: 'Sidoaxel', rear_delt: 'Bakre axel',
  biceps: 'Biceps', triceps: 'Triceps', quads: 'Framsida lår', hamstrings: 'Baksida lår', glutes: 'Säte', calves: 'Vader', abs: 'Mage',
  traps: 'Trapezius', forearms: 'Underarmar',
};

/** Equipment an exercise needs. 'gym' means a full gym (barbell, machines, cables). */
export type Need = 'barbell' | 'machine' | 'cable' | 'dumbbell' | 'bench' | 'pullup_bar' | 'dip_bars' | 'band';

export type Group = 'Ben' | 'Bröst' | 'Rygg' | 'Axlar' | 'Armar' | 'Mage' | 'Färdighet' | 'Höftrehab';
export const GROUPS: Group[] = ['Ben', 'Bröst', 'Rygg', 'Axlar', 'Armar', 'Mage', 'Färdighet', 'Höftrehab'];

export interface Exercise {
  id: string;
  name: string;
  group: Group;
  primary: Muscle[];
  secondary: Muscle[];
  needs: Need[]; // empty = no equipment
  compound: boolean;
  reps: [number, number];
  unit?: 'reps' | 'sek';
  step: number; // kg per increase; 0 = bodyweight
  rest: number; // seconds
  cue: string;
  tips: [string, string, string];
  easier?: string; // progression ladder
  harder?: string;
  alt?: string[]; // substitutes in order, when equipment is missing
  why?: string; // why it is in the library (source)
}

const E = (e: Exercise) => e;

